library(causatr)
library(tinytable)

compare_row &lt;- function(label, result, name, ref_name,
                        ref_est, ref_se, level = 0.95) {
  con &lt;- result$contrasts
  est &lt;- result$estimates
  if (name %in% con$comparison) {
    row &lt;- con[con$comparison == name, ]
  } else if (name %in% est$intervention) {
    row &lt;- est[est$intervention == name, ]
  } else {
    stop(
      "name '", name,
      "' not found in result$contrasts$comparison or result$estimates$intervention"
    )
  }
  stopifnot(
    length(ref_est) == 1L && is.finite(ref_est),
    length(ref_se) == 1L && is.finite(ref_se)
  )
  z &lt;- stats::qnorm(1 - (1 - level) / 2)

  # Three rows: causatr, reference, and a row of absolute differences.
  # The diff row is the whole point of the vignette — it makes
  # "do the two implementations agree?" visually obvious without making
  # the reader compare two numbers to 6 decimal places.
  est_c &lt;- row$estimate
  se_c  &lt;- row$se
  ci_lc &lt;- row$ci_lower
  ci_uc &lt;- row$ci_upper
  ci_lr &lt;- ref_est - z * ref_se
  ci_ur &lt;- ref_est + z * ref_se

  dt &lt;- data.table::data.table(
    source   = c("causatr", ref_name, "abs diff"),
    estimate = c(est_c, ref_est, abs(est_c - ref_est)),
    se       = c(se_c,  ref_se,  abs(se_c  - ref_se)),
    ci_lower = c(ci_lc, ci_lr,   abs(ci_lc - ci_lr)),
    ci_upper = c(ci_uc, ci_ur,   abs(ci_uc - ci_ur))
  )

  tinytable::tt(dt, caption = label) |&gt;
    tinytable::format_tt(
      j = 2:5, digits = 4, num_fmt = "decimal"
    ) |&gt;
    tinytable::style_tt(i = 3, italic = TRUE, color = "#888")
}



DGM 1：点处理（simulate_point()）
单个混杂因子 \(L\)、二值处理 \(A\) 和结局 \(Y\)（连续或二值，取决于 binary_outcome 标志）。两个版本共享相同的混杂结构：\(L\) 同时影响处理分配和结局。
连续结局（binary_outcome = FALSE）：
\[
\begin{aligned}
L &\sim \mathcal{N}(0, 1) \\
A &\sim \text{Bernoulli}\bigl(\text{logit}^{-1}(0.4 \, L)\bigr) \\
Y &= 1 + 2 A + 0.5 \, L + \varepsilon, \quad \varepsilon \sim \mathcal{N}(0, 0.8^2)
\end{aligned}
\]
\(A\) 的结构系数为 2，因此真实 ATE 恰好为 2。
二值结局（binary_outcome = TRUE）：
\[
\begin{aligned}
L &\sim \mathcal{N}(0, 1) \\
A &\sim \text{Bernoulli}\bigl(\text{logit}^{-1}(0.4 \, L)\bigr) \\
Y &\sim \text{Bernoulli}\bigl(\text{logit}^{-1}(-0.5 + 0.8 \, A + 0.3 \, L)\bigr)
\end{aligned}
\]
条件比值比为 \(\exp(0.8) \approx 2.23\)。


DGM 2：纵向二值（simulate_longitudinal()）
\(K\) 个时期，含二值处理、一个时变混杂因子和一个随访结束时的二值结局。存在 处理—混杂因子反馈：过去的处理会平移下一期混杂因子的分布。
\[
\begin{aligned}
L_k &\sim \mathcal{N}(0, 1) + 0.3 \, A_{k-1} \quad (A_0 \equiv 0) \\
A_k &\sim \text{Bernoulli}\bigl(\text{logit}^{-1}(0.3 \, L_k)\bigr) \\
Y   &\sim \text{Bernoulli}\!\left(\text{logit}^{-1}\!\left(-1 + 0.4 \sum_{k=1}^{K} A_k + 0.2 \, L_K\right)\right)
\end{aligned}
\]
处理—混杂因子反馈（\(L_k\) 依赖于 \(A_{k-1}\)）意味着朴素地对时变混杂因子做条件化会 产生偏倚；需要 G-computation（ICE）或带序贯权重的 IPW。


DGM 3：纵向连续（simulate_longitudinal_continuous()）
\(K\) 个时期，含连续（高斯）处理和连续结局。与 DGM 2 相同的处理—混杂因子反馈 结构，但全程使用连续变量。
\[
\begin{aligned}
L_k &\sim \mathcal{N}(0, 1) + 0.2 \, A_{k-1} \quad (A_0 \equiv 0) \\
A_k &\sim \mathcal{N}(0.3 \, L_k,\; 1) \\
Y   &= 1 + \sum_{k=1}^{K} A_k + 0.3 \, L_K + \varepsilon, \quad \varepsilon \sim \mathcal{N}(0, 0.5^2)
\end{aligned}
\]
在给每个时期的处理都加 1 的 shift(+1) 干预下，每个时期对结局恰好贡献 1 个单位， 因此 shift(+1) 相对自然值的真实因果效应为 \(K\)。在默认的 \(K = 2\) 下，真值为 2。
simulate_point &lt;- function(n = 2000, seed = 1L, binary_outcome = FALSE) {
  set.seed(seed)
  L &lt;- stats::rnorm(n)
  A &lt;- stats::rbinom(n, 1L, stats::plogis(0.4 * L))
  if (binary_outcome) {
    Y &lt;- stats::rbinom(n, 1L, stats::plogis(-0.5 + 0.8 * A + 0.3 * L))
  } else {
    Y &lt;- 1 + 2 * A + 0.5 * L + stats::rnorm(n, sd = 0.8)
  }
  data.frame(L = L, A = A, Y = Y)
}

simulate_longitudinal &lt;- function(n = 500L, K = 3L, seed = 2L) {
  set.seed(seed)
  L &lt;- matrix(0, n, K)
  A &lt;- matrix(0L, n, K)
  for (k in seq_len(K)) {
    L[, k] &lt;- stats::rnorm(n) +
      if (k == 1L) 0 else 0.3 * A[, k - 1L]
    A[, k] &lt;- stats::rbinom(n, 1L, stats::plogis(0.3 * L[, k]))
  }
  Y &lt;- stats::rbinom(n, 1L, stats::plogis(-1 + 0.4 * rowSums(A) + 0.2 * L[, K]))
  wide &lt;- data.table::data.table(id = seq_len(n))
  for (k in seq_len(K)) {
    wide[[paste0("L", k)]] &lt;- L[, k]
    wide[[paste0("A", k)]] &lt;- A[, k]
  }
  wide$Y &lt;- Y
  wide[]
}

simulate_longitudinal_continuous &lt;- function(n = 400L, K = 2L, seed = 3L) {
  set.seed(seed)
  L &lt;- matrix(0, n, K)
  A &lt;- matrix(0, n, K)
  for (k in seq_len(K)) {
    L[, k] &lt;- stats::rnorm(n) +
      if (k == 1L) 0 else 0.2 * A[, k - 1L]
    A[, k] &lt;- stats::rnorm(n, mean = 0.3 * L[, k], sd = 1)
  }
  Y &lt;- 1 + rowSums(A) + 0.3 * L[, K] + stats::rnorm(n, sd = 0.5)
  wide &lt;- data.table::data.table(id = seq_len(n))
  for (k in seq_len(K)) {
    wide[[paste0("L", k)]] &lt;- L[, k]
    wide[[paste0("A", k)]] &lt;- A[, k]
  }
  wide$Y &lt;- Y
  wide[]
}

估计因果效应
现在，我们可以使用 ATE 权重，尝试在朴素线性回归模型中控制混杂。 在这个例子中，拟合这样的模型相当简单：仍然拟合之前的模型，只需加上 weights = wts，即可纳入逆概率权重。

net_data_wts |&gt;
  lm(malaria_risk ~ net, data = _, weights = wts) |&gt;
  tidy(conf.int = TRUE)

# A tibble: 2 x 7
  term   estimate std.error statistic  p.value conf.low
  &lt;chr&gt;     &lt;dbl&gt;     &lt;dbl&gt;     &lt;dbl&gt;    &lt;dbl&gt;    &lt;dbl&gt;
1 (Inte~     42.7     0.442      96.7 0            41.9
2 netTR~    -12.5     0.624     -20.1 5.50e-81    -13.8
# i 1 more variable: conf.high &lt;dbl&gt;


平均处理效应的估计值为 -12.5 (95% CI -13.8, -11.3)。 遗憾的是，我们目前使用的置信区间并不正确，因为它们没有考虑权重估计过程中的不确定性。 一般来说，如果不考虑这种不确定性，倾向评分加权模型的置信区间就会过窄。 因此，置信区间的实际覆盖率与标称覆盖率不符（它们并不是 95% 置信区间，因为实际覆盖率远低于 95%），这可能导致错误解读。
有几种方法可以解决这个问题，我们将在 ?sec-outcome-model 中详细讨论，包括 Bootstrap、稳健标准误，以及使用经验三明治估计量显式考虑估计过程。 在这个例子中，我们将使用 Bootstrap，它是一种通过重抽样计算参数分布的灵活工具。 对于许多因果模型，如果相关问题（尤其是标准误）没有闭式解，或者我们希望避免许多此类解所固有的参数假设，Bootstrap 都是一个有用的工具；关于 Bootstrap 是什么以及它如何运作，请参阅 ?sec-appendix-bootstrap 。 我们将使用 tidymodels 生态系统中的 {rsample} 包来处理 Bootstrap 样本。
正因为 Bootstrap 非常灵活，我们需要仔细思考所计算统计量的不确定性来源。 我们可能很容易想到写出下面这样的函数，来估计感兴趣的统计量（netTRUE 的点估计值）：

library(rsample)

fit_ipw_not_quite_rightly &lt;- function(.split, ...) {
  # get bootstrapped data frame
  .df &lt;- as.data.frame(.split)

  # fit ipw model
  lm(malaria_risk ~ net, data = .df, weights = wts) |&gt;
    tidy()
}

然而，这个函数无法给出正确的置信区间，因为它把逆概率权重当成了固定值。 当然，它们并不是固定值；我们刚刚才用逻辑回归估计出这些权重！ 我们需要对整个建模过程进行 Bootstrap，以考虑这种不确定性。 对于每一个 Bootstrap 样本，我们都需要拟合倾向评分模型，计算逆概率权重，然后拟合加权结局模型。

library(rsample)

fit_ipw &lt;- function(.split, ...) {
  # get bootstrapped data frame
  .df &lt;- as.data.frame(.split)

  # fit propensity score model
  propensity_model &lt;- glm(
    net ~ income + health + temperature,
    data = .df,
    family = binomial()
  )

  # calculate inverse probability weights
  .df &lt;- propensity_model |&gt;
    augment(type.predict = "response", data = .df) |&gt;
    mutate(wts = wt_ate(.fitted, net))

  # fit correctly bootstrapped ipw model
  lm(malaria_risk ~ net, data = .df, weights = wts) |&gt;
    tidy()
}

现在，我们已经明确了每次迭代中如何计算估计值，接下来用 rsample 的 bootstraps() 函数创建 Bootstrap 数据集。 times 参数决定创建多少个 Bootstrap 数据集；这里我们创建 1,000 个。

bootstrapped_net_data &lt;- bootstraps(
  net_data,
  times = 1000,
  # required to calculate CIs later
  apparent = TRUE
)

bootstrapped_net_data

# Bootstrap sampling with apparent sample 
# A tibble: 1,001 x 2
   splits             id           
   &lt;list&gt;             &lt;chr&gt;        
 1 &lt;split [1752/657]&gt; Bootstrap0001
 2 &lt;split [1752/641]&gt; Bootstrap0002
 3 &lt;split [1752/632]&gt; Bootstrap0003
 4 &lt;split [1752/647]&gt; Bootstrap0004
 5 &lt;split [1752/626]&gt; Bootstrap0005
 6 &lt;split [1752/622]&gt; Bootstrap0006
 7 &lt;split [1752/650]&gt; Bootstrap0007
 8 &lt;split [1752/659]&gt; Bootstrap0008
 9 &lt;split [1752/640]&gt; Bootstrap0009
10 &lt;split [1752/687]&gt; Bootstrap0010
# i 991 more rows


结果是一个嵌套数据框：每个 splits 对象都包含元数据，rsample 利用这些元数据从原始数据中提取相应的 Bootstrap 样本，共得到 1,000 个样本。 实际上，结果有 1,001 行，因为 apparent = TRUE 还保留了一份原始数据框副本，某些类型的置信区间计算需要用到它。 接下来，我们将运行 fit_ipw() 1,001 次，构建 estimate 的分布。 我们所做计算的核心是
fit_ipw(bootstrapped_net_data$splits[[n]])
其中，n 是 1,001 个索引中的一个。 我们将使用 purrr 的 map() 函数，依次遍历每个 split 对象。

ipw_results &lt;- bootstrapped_net_data |&gt;
  mutate(boot_fits = map(splits, fit_ipw))

ipw_results

