# i 991 more rows


结果是另一个嵌套数据框，其中新增了一列 boot_fits。 boot_fits 的每个元素都是相应 Bootstrap 数据集的 IPW 结果。 例如，第一个 Bootstrap 数据集的 IPW 结果为：

ipw_results$boot_fits[[1]]

# A tibble: 2 x 5
  term        estimate std.error statistic  p.value
  &lt;chr&gt;          &lt;dbl&gt;     &lt;dbl&gt;     &lt;dbl&gt;    &lt;dbl&gt;
1 (Intercept)     42.7     0.436      98.0 0       
2 netTRUE        -12.9     0.615     -20.9 4.28e-87


现在，我们得到了估计值的分布：

ipw_results |&gt;
  # remove original data set results
  filter(id != "Apparent") |&gt;
  mutate(
    estimate = map_dbl(
      boot_fits,
      # pull the `estimate` for `netTRUE` for each fit
      \(.fit) {
        .fit |&gt;
          filter(term == "netTRUE") |&gt;
          pull(estimate)
      }
    )
  ) |&gt;
  ggplot(aes(estimate)) +
  geom_histogram(fill = "#D55E00FF", color = "white", alpha = 0.8)







图 56.8: “A histogram of 1,000 bootstrapped estimates of the effect of net use on malaria risk. The spread of these estimates accounts for the dependency and uncertainty in the use of IPW weights.”





图 56.8 展示了 estimate 的变异情况，接下来用 rsample 的 int_t()，根据 Bootstrap 分布计算 95% 置信区间：

boot_estimate &lt;- ipw_results |&gt;
  # calculate T-statistic-based CIs
  int_t(boot_fits) |&gt;
  filter(term == "netTRUE")

boot_estimate

# A tibble: 1 x 6
  term    .lower .estimate .upper .alpha .method  
  &lt;chr&gt;    &lt;dbl&gt;     &lt;dbl&gt;  &lt;dbl&gt;  &lt;dbl&gt; &lt;chr&gt;    
1 netTRUE  -13.3     -12.6  -11.7   0.05 student-t


现在，我们得到了经过混杂因子调整、且标准误正确的估计值。 所有家庭都使用蚊帐与没有任何家庭使用蚊帐相比，对疟疾风险的效应估计值为 -12.6 (95% CI -13.3, -11.7)。 在这项研究中，蚊帐看起来确实能够降低疟疾风险。

参数化结局模型
可以把分层理解为计算条件均值。 条件均值的一个更一般化的扩展是多变量线性回归。 当我们以 outcome ~ exposure + confounder1 + confounder2 + ... 的形式使用 lm() 拟合模型时，拟合的就是所谓的结局模型；之所以这样称呼，是因为我们将暴露和混杂因子作为自变量，以结局作为因变量进行拟合。 这有时也称为直接调整或回归调整，因为我们直接在回归模型中调整混杂因子。 让我们使用 lm() 计算本例中两个二元混杂因子情况下的效应：

library(broom)
lm(
  satisfaction ~ update_frequency + customer_type + business_hours,
  data = satisfaction2
) |&gt;
  tidy(conf.int = TRUE) |&gt;
  filter(term == "update_frequencydaily") |&gt;
  select(estimate, starts_with("conf"))

# A tibble: 1 x 3
  estimate conf.low conf.high
     &lt;dbl&gt;    &lt;dbl&gt;     &lt;dbl&gt;
1 -0.00906  -0.0411    0.0230


对于连续混杂因子，这种方法同样效果很好，因为不再需要先分箱就能得到正确答案：

lm(
  satisfaction ~ update_frequency + num_users,
  data = satisfaction3
) |&gt;
  tidy(conf.int = TRUE) |&gt;
  filter(term == "update_frequencydaily") |&gt;
  select(estimate, starts_with("conf"))

# A tibble: 1 x 3
  estimate  conf.low conf.high
     &lt;dbl&gt;     &lt;dbl&gt;     &lt;dbl&gt;
1  0.00153 -0.000595   0.00366


不过，这种推广并非没有代价：现在我们引入了参数统计模型，以便在数据稀疏的区域进行估计。 对于 satisfaction ~ update_frequency + num_users，得到的估计值恰好是正确答案，因为 lm() 背后的统计模型与我们的模拟完全匹配。 例如，satisfaction 与 num_users 之间的关系是线性的，因此拟合该模型时不会受到维度问题的影响（尽管线性回归在行数和列数方面也有自身的限制）。 换句话说，现在我们依赖于正确的函数形式，即模型中变量之间关系的数学表达形式（更多细节见 Tip 60.2）。 暴露和混杂因子都需要采用正确的函数形式。 要做好建模，需要理解这些变量与结局之间关系的性质。






警告 60.2: 参数模型中的函数形式



在正文中，我们模拟的结局与混杂因子之间的关系是线性的，也就是说，它完全满足 lm() 的基础假设，所以拟合参数模型时得到了正确答案。 如果模拟数据不符合 lm() 的基础假设，会发生什么？ 让我们来看看。

set.seed(11)
satisfaction4 &lt;- tibble(
  # Number of users
  num_users = runif(n, 1, 500),
  # Larger customers more likely to have daily updates
  update_frequency = rbinom(n, 1, plogis(num_users / 100)),
  # non-linear relationship between satisfaction and number of users
  satisfaction = 70 - 0.001 * (num_users - 300)^2 - 0.001 * (num_users - 300)^3
) |&gt;
  mutate(
    satisfaction = as.numeric(scale(satisfaction)),
    update_frequency = factor(
      update_frequency,
      labels = c("weekly", "daily")
    )
  )
ggplot(satisfaction4, aes(x = num_users, y = satisfaction)) +
  geom_line()








从上图可以看到，现在混杂因子（用户数量）与结局（满意度）之间呈现非线性关系。 让我们看看对这些数据拟合一个（错误的）参数模型会发生什么。

lm(
  satisfaction ~ update_frequency + num_users,
  data = satisfaction4
) |&gt;
  tidy(conf.int = TRUE) |&gt;
  filter(term == "update_frequencydaily") |&gt;
  select(estimate, starts_with("conf"))

# A tibble: 1 x 3
  estimate conf.low conf.high
     &lt;dbl&gt;    &lt;dbl&gt;     &lt;dbl&gt;
1   -0.189   -0.219    -0.159


我们的估计值离真实值很远（真实值应为 0）；真实值甚至不在置信区间内。 哪里出了问题？ 我们的参数模型假设用户数量与满意度之间的关系是线性的，但我们生成的数据呈现非线性关系。 有一种解决方案仍然允许使用参数模型：如果我们知道真实的函数形式，就可以使用它。 看看这样会得到什么结果。

lm(
  satisfaction ~ update_frequency + poly(num_users, 3),
  data = satisfaction4
) |&gt;
  tidy(conf.int = TRUE) |&gt;
  filter(term == "update_frequencydaily") |&gt;
  select(estimate, starts_with("conf"))

# A tibble: 1 x 3
  estimate conf.low conf.high
     &lt;dbl&gt;    &lt;dbl&gt;     &lt;dbl&gt;
1 1.47e-15 1.20e-15  1.74e-15


很好！ 现在，这个模型与数据的生成方式完全一致，我们再次得到了完全正确的答案。 在现实世界中，我们通常不知道数据生成机制，但仍然可以拟合灵活的参数模型。 一个很好的方法是使用自然三次样条。

lm(
  satisfaction ~ update_frequency + splines::ns(num_users, 3),
  data = satisfaction4
) |&gt;
  tidy(conf.int = TRUE) |&gt;
  filter(term == "update_frequencydaily") |&gt;
  select(estimate, starts_with("conf"))

# A tibble: 1 x 3
  estimate conf.low conf.high
     &lt;dbl&gt;    &lt;dbl&gt;     &lt;dbl&gt;
1  0.00216 -0.00258   0.00690


我们也可以使用原来的非参数方法；如果将数据分成 20 个箱进行分层，也能得到偏倚较小的估计值（即非常接近真实值 0）。

satisfaction4_strat &lt;- satisfaction4 |&gt;
  mutate(num_users_q = ntile(num_users, 20)) |&gt;
  group_by(num_users_q, update_frequency) |&gt;
  summarise(
    avg_satisfaction = mean(satisfaction),
    .groups = "drop"
  )

satisfaction4_strat |&gt;
  ungroup() |&gt;
  pivot_wider(
    names_from = update_frequency,
    values_from = avg_satisfaction
  ) |&gt;
  summarise(estimate = mean(daily - weekly))

# A tibble: 1 x 1
  estimate
     &lt;dbl&gt;
1 -0.00817




之后我们还会探索使用机器学习等数据自适应方法来减弱这一假设（?sec-causal-ml）。

当我们满足所用模型估计量的假设时，结局回归可以发挥很好的作用。 例如，如果我们理解结局与回归模型中各变量之间的关系，并且相信模型的假设，尤其是线性假设，那么 OLS 可能非常有益。 从统计角度看，它的效率很高（也就是说，我们会得到较小的标准误）。 此外，无需使用 Bootstrap（见 ?sec-appendix-bootstrap），我们也能得到名义上正确的置信区间。 科学家以及其他分析数据的人通常也熟悉线性回归，因此更容易理解你是如何计算因果效应的。 事实上可以说，当结局与暴露之间存在线性关系，并且满足 因果假设 中列出的因果假设时，相关就是因果。
那么，我们为什么不总是使用结局模型来计算因果效应？ 首先，与对结局建模相比，我们可能更有把握对暴露建模（例如逆概率模型）。 我们将在 ?sec-g-comp 和 ?sec-dr 中进一步探讨这一想法。 相关地，当结局为二元变量时，根据事件数量选择其中一种方法可能更合理。 例如，如果结局罕见而暴露并不罕见，使用倾向评分方法在统计上可能更有效。 其次，使用结局模型有时难以得到我们所针对的估计值——即对一个精确问题的回答——我们将在 ?sec-estimands 中更深入地讨论这一点。
此外，结局模型给出的是条件效应。 换句话说，在描述估计系数时，我们经常会说：“暴露增加一个单位，会使结局改变 coefficient，同时模型中的所有其他变量保持不变。” 在因果推断中，我们通常对边际效应感兴趣。 从数学上说，这意味着我们希望针对某个要估计因果效应的特定人群，在该人群中各因素的分布上对所关注的效应取平均。 当结局是连续的、效应是线性的，并且暴露效应与人群的其他因素之间不存在交互作用时，条件效应与边际效应之间的区别在很大程度上只是语义上的。 两者的估计值会完全相同。
如果模型中存在交互作用，也就是说，暴露对结局的影响取决于某个其他因素，那么我们就不再有一个可以解释的单一系数。 我们可能希望在考虑目标人群中该因素分布的情况下估计边际效应。 为什么？ 我们的最终目标是判断是否应该建议目标人群接受该暴露，因此我们想知道，平均而言，这种暴露是否有益。
考虑 图 60.1 的一种变体，其中更新频率确实会对满意度产生因果效应，但该效应因客户类型而异。 对于高级客户，每日更新会使满意度提高 5 分。 对于免费客户，每日更新会使满意度降低 5 分。 改变更新频率的效应是异质的，取决于客户类型。 是否值得让所有人都改为每日更新，取决于高级客户与免费客户的分布。

如果 50% 的客户是高级客户，50% 是免费客户，那么切换为每日更新的平均效应为：
\((0.5 * 5) + (0.5 * -5) = 0\)
如果 100% 的客户都是高级客户，那么平均效应为：
\((1 * 5) + (0 * -5) = 5\)
如果 100% 的客户都是免费客户，那么平均效应为：
\((0 * 5) + (1 * -5) = -5\)

边际化告诉我们数据中协变量分布对应的平均效应。 当然，我们可能希望按客户类型估计因果效应；我们将在 ?sec-interaction 中深入讨论交互作用效应。






注记



在 Logistic 回归和 Cox 回归模型中，条件效应会更加复杂；正如我们将在 ?sec-non-collapse 中看到的，这类模型的条件系数会根据模型中包含的变量不同而回答完全不同的问题。


有时我们也不能使用结局模型。 第一种情况是，我们认为自己无法满足无混杂方法的假设。 在这种情况下，我们同样不能使用逆概率加权及其他相关方法。 不过，我们可能可以使用另一种方法，例如工具变量分析、回归不连续或双重差分（?sec-iv-friends 和 ?sec-did；下面也会对这些方法进行总结）。 第二种情况是暴露和混杂随时间变化。 线性回归无法在不产生偏倚的情况下估计这类效应，因此需要使用逆概率加权或 g 计算等方法才能正确计算。 在本书的大部分内容中，我们将分析简单的前后数据：有基线数据，在单个时间点发生暴露，并在暴露之后出现结局。 在 ?sec-longitudinal 及其他章节中，我们将讨论更复杂的问题和数据。

为什么有效？
为什么这个极其简单的算法能在如此多的问题上表现良好？ 关于自助法的技术细节，请参阅其原始论文和著作 (Efron 1979; Efron 和 Tibshirani 1993)。 但让我们先对其运作方式建立一些直觉。
考虑一个我们想要了解的总体。 有时我们拥有总体中每个观测的资料，但更多时候，我们需要出于必要性或效率考虑从总体中抽样。

library(tidyverse)
n &lt;- 1000000
population &lt;- tibble(
  z = rnorm(n),
  x = z + rnorm(n),
  y = x + z + rnorm(n)
)

population 包含 100 万个观测，但我们将从整个总体中随机抽取 200 个观测。 如果还需要进行更多次抽样，我们会独立于原始样本进行。 某个观测可能最终出现在不止一项研究中。 假设已经从同一总体中完成了 20 项这样的研究。

samples &lt;- map(1:20, ~ population[sample(n, size = 200), ]) |&gt;
  bind_rows(.id = "sample") |&gt;
  mutate(sample = as.numeric(sample))

由于随机抽样变异，每个样本的 x 均值都略有不同于 population 中的均值，后者为 -6.8199^{-4}。 这些样本估计值都在总体估计值附近波动（图 80.3）。

sample_means &lt;- samples |&gt;
  group_by(sample) |&gt;
  summarize(across(everything(), mean))

samples |&gt;
  ggplot(aes(x = x)) +
  geom_histogram() +
  geom_vline(
    data = sample_means,
    aes(xintercept = x),
    color = "firebrick"
  ) +
  facet_wrap(~sample)







图 80.3: The distributions of the sample means of x for twenty samples. Each sample is sampled from population and has a sample size of 200.





你可能会注意到，从总体中抽样与我们在自助法中进行的抽样有相似之处。 我们把重采样视为其来源总体的代表。 这有助于我们将所看到的分布转换为原始总体的尺度，方式与使用参数置信区间时大致相同。 与从总体中抽样的一个关键区别是，自助法确定的是围绕样本估计值的离散程度，而不是围绕总体估计值的离散程度。 让我们更仔细地看看样本 8。

sample_8 &lt;- samples |&gt;
  filter(sample == "8")

sample_8 |&gt;
  summarize(across(everything(), mean))

